add_action( 'woocommerce_after_single_product_summary', 'perfectpixel_second_atc_form', 9999 );

function perfectpixel_second_atc_form() {
	global $product;
	if ( ! $product || ! $product->is_purchasable() || ! $product->is_in_stock() ) {
		return;
	}
	echo '<div class="perfectpixel-second-atc" style="clear:both;padding-top:1.5em">';
	woocommerce_template_single_add_to_cart();
	echo '</div>';
}
